const b = $input.first().json.body || {};
const errs = [];
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(b.personalEmail || ''))) errs.push('personalEmail invalid');
if (!b.firstName || !b.lastName) errs.push('name missing');
if (!b.startDate) errs.push('startDate missing');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(b.managerEmail || ''))) errs.push('managerEmail invalid');

const start = b.startDate ? new Date(b.startDate) : null;
const today = new Date();
const daysUntilStart = start ? Math.ceil((start - today) / 86400000) : null;
const domain = String(b.personalEmail || '').split('@')[1] || 'example.com';
const workEmail = b.workEmail || `${String(b.firstName).toLowerCase()}.${String(b.lastName).toLowerCase()}@company.example`.replace(/[^a-z0-9.@-]/g, '');

const checklist = [
  'create google workspace account',
  'assign laptop',
  'create notion onboarding page',
  'add to slack channels',
  'schedule day-1 buddy',
  ...(b.department === 'Engineering' ? ['grant repo access', 'assign dev laptop image'] : []),
  ...(b.department === 'Finance' ? ['grant ERP read access', 'request NDA signature'] : []),
];

return [{ json: {
  ...b, isValid: errs.length === 0, validationErrors: errs,
  daysUntilStart, workEmail, personalDomain: domain,
  checklist, checklistText: checklist.map((c, i) => `${i + 1}. ${c}`).join('\n'),
}}];

