const b = $input.first().json.body || {};
const last = b.lastWorkingDay ? new Date(b.lastWorkingDay) : new Date();
const days = Math.ceil((last - new Date()) / 86400000);
const steps = [
  'disable SSO / workspace account',
  'revoke repo + cloud access',
  'collect laptop & badge',
  'forward mailbox for 30 days',
  'remove from Slack + distribution lists',
  'schedule exit interview',
];
return [{ json: {
  ...b, daysUntilOffboarding: days,
  steps, stepsText: steps.map((s, i) => `${i + 1}. ${s}`).join('\n'),
  disableUrl: `https://admin.googleapis.com/admin/directory/v1/users/${encodeURIComponent(b.workEmail || '')}`,
}}];
